// SPDX-License-Identifier: MIT
pragma solidity 0.8.3;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/SINCEREBAT.sol";

contract SINCEREBATTest is Test {
    // Fixed router address used in contract constructor
    address constant ROUTER_ADRESS = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address mockFactory = address(0xABCD);
    address mockWETH = address(0x1);
    address mockPair = address(0x2);

    SINCEREBAT token;
    address deployer = address(0x1);
    address sender = address(0x3);
    address receiver = address(0x4);
    uint256 constant TEST_AMOUNT = 100 ether;

    function setUp() public {
        vm.startPrank(deployer);

        // Mock Uniswap router/factory calls
        vm.mockCall(
            ROUTER_ADRESS,
            abi.encodeWithSignature("factory()"),
            abi.encode(mockFactory)
        );
        vm.mockCall(
            ROUTER_ADRESS,
            abi.encodeWithSignature("WETH()"),
            abi.encode(mockWETH)
        );
        vm.mockCall(
            mockFactory,
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(mockPair)
        );

        // Deploy token contract
        token = new SINCEREBAT();

        // Provide test tokens to sender
        token.transfer(sender, 1000 ether);
        vm.stopPrank();
    }

    function testFeeManipulation() public {
        console2.log("--- BEFORE-Trigger Transfer ---");
        (uint256 txFeeBefore,) = _executeTransferAndCalcFee();
        console2.log("Initial tax rate:", (txFeeBefore * 100) / TEST_AMOUNT, "%");

        console2.log("--- Trigger ChangeFee ---");
        // Vulnerability activation: set tax fee to 100%
        vm.prank(deployer);
        token.setTaxFeePercent(100);

        console2.log("--- AFTER-Trigger Transfer ---");
        (uint256 txFeeAfter,) = _executeTransferAndCalcFee();
        console2.log("Manipulated tax rate:", (txFeeAfter * 100) / TEST_AMOUNT, "%");

        // Final verification and verdict
        if (txFeeAfter == TEST_AMOUNT) {
            console2.log("Vulnerability Exists: Tax fee successfully manipulated to 100%");
        } else {
            console2.log("Vulnerability not Exist: Tax fee manipulation failed");
        }
    }

    function _executeTransferAndCalcFee() private returns (uint256 feeAmount, uint256 receivedAmount) {
        // Record initial balances
        uint256 senderBalBefore = token.balanceOf(sender);
        uint256 receiverBalBefore = token.balanceOf(receiver);

        // Execute transfer
        vm.prank(sender);
        token.transfer(receiver, TEST_AMOUNT);

        // Calculate results
        uint256 senderBalAfter = token.balanceOf(sender);
        uint256 receiverBalAfter = token.balanceOf(receiver);

        receivedAmount = receiverBalAfter - receiverBalBefore;
        feeAmount = TEST_AMOUNT - receivedAmount;

        return (feeAmount, receivedAmount);
    }
}
